// ---------------------------------------------------------------------------
// Live game fallback: websockets arrive through Turbo stream sources; if a
// connection is not available, poll the tiny state endpoint and refresh with
// Turbo once the game version moves on. No full page reload, ever.
// ---------------------------------------------------------------------------

(function () {
  "use strict";

  function cableConnected() {
    var sources = document.querySelectorAll("turbo-cable-stream-source");
    for (var i = 0; i < sources.length; i += 1) {
      if (sources[i].hasAttribute("connected")) return true;
    }
    return false;
  }

  function refreshPage() {
    if (window.Turbo) {
      window.Turbo.visit(window.location.href, { action: "replace" });
    } else {
      window.location.reload();
    }
  }

  function initializeLive() {
    if (window.__quizzyLiveTimer) {
      window.clearInterval(window.__quizzyLiveTimer);
      window.__quizzyLiveTimer = null;
    }

    var node = document.querySelector("[data-live]");
    if (!node || !node.dataset.stateUrl || !window.fetch) return;

    var stateUrl = node.dataset.stateUrl;
    var version = String(node.dataset.version || "");
    var refreshing = false;

    window.__quizzyLiveTimer = window.setInterval(function () {
      if (refreshing || cableConnected()) return;

      fetch(stateUrl, {
        credentials: "same-origin",
        headers: { "Accept": "application/json" },
        cache: "no-store"
      }).then(function (response) {
        return response.ok ? response.json() : null;
      }).then(function (data) {
        if (!data || refreshing) return;
        if (String(data.version) === version) return;

        refreshing = true;
        refreshPage();
      }).catch(function () {
        // Network hiccup: try again on the next tick.
      });
    }, 1200);
  }

  document.addEventListener("turbo:load", initializeLive);
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initializeLive, { once: true });
  } else {
    initializeLive();
  }
})();
EOF
